values.value:
{
  "fields": [
    {
      "apiName": "customer_address_folder",
      "label": "Customer Address",
      "type": "folder",
      "iconColor": "blue",
      "controllingField": "incoterms",
      "controllingValues": [
        "FOR"
      ],
      "modalConfigsByValue": {
        "default": {
          "title": "CUSTOMER ADDRESS",
          "modalFields": [
            {
              "id": "billing_address",
              "label": "Billing Address",
              "expanded": true,
              "fields": [
                {
                  "apiName": "ba_street",
                  "label": "STREET",
                  "type": "text",
                  "readOnly": true,
                  "defaultValue": "@@BillingStreet@@",
                  "colSpan": 12
                },
                {
                  "apiName": "ba_city",
                  "label": "CITY",
                  "type": "text",
                  "readOnly": true,
                  "defaultValue": "@@BillingCity@@",
                  "colSpan": 12
                },
                {
                  "apiName": "ba_zip_code",
                  "label": "ZIP-CODE",
                  "type": "text",
                  "readOnly": true,
                  "defaultValue": "@@BillingPostalCode@@",
                  "colSpan": 12
                },
                {
                  "apiName": "ba_state",
                  "label": "STATE",
                  "type": "text",
                  "readOnly": true,
                  "defaultValue": "@@BillingState@@",
                  "colSpan": 12
                },
                {
                  "apiName": "ba_country",
                  "label": "COUNTRY",
                  "type": "text",
                  "readOnly": true,
                  "defaultValue": "@@BillingCountry@@",
                  "colSpan": 12
                },
                {
                  "apiName": "ba_phone",
                  "label": "PHONE NUMBER",
                  "type": "text",
                  "readOnly": true,
                  "defaultValue": "@@Phone@@",
                  "colSpan": 12
                },
                {
                  "apiName": "ba_email",
                  "label": "EMAIL",
                  "type": "text",
                  "readOnly": true,
                  "defaultValue": "@@Email__c@@",
                  "colSpan": 12
                },
                {
                  "apiName": "ba_website",
                  "label": "WEBSITE",
                  "type": "text",
                  "readOnly": true,
                  "defaultValue": "@@Website@@",
                  "colSpan": 12
                }
              ]
            }
          ]
        }
      }
    },
    {
      "apiName": "terms_and_conditions_folder",
      "label": "Terms & Conditions",
      "type": "folder",
      "iconColor": "red",
      "controllingField": "incoterms",
      "controllingValues": [
        "*"
      ],
      "modalConfigsByValue": {
        "default": {
          "title": "TERMS & CONDITIONS",
          "modalFields": [
            {
              "id": "tc_details",
              "label": "Terms & Condition Details",
              "expanded": true,
              "fields": [
                {
                  "apiName": "tc_subject_line",
                  "label": "Subject Line",
                  "type": "textarea",
                  "colSpan": 6
                },
                {
                  "apiName": "tc_advance_payment",
                  "label": "ADVANCE PAYMENT %",
                  "type": "number",
                  "defaultValue": 30,
                  "colSpan": 6
                },
                {
                  "apiName": "tc_warranty_in_months",
                  "label": "Warranty (in months)",
                  "type": "number",
                  "defaultValue": 12,
                  "colSpan": 6
                },
                {
                  "apiName": "tc_delivery_days",
                  "label": "Delivery Days",
                  "type": "text",
                  "defaultValue": "45-60",
                  "colSpan": 6
                }
              ]
            },
            {
              "id": "payment_terms_section",
              "label": "Payment Terms",
              "expanded": true,
              "fields": [
                {
                  "apiName": "tc_payment_terms_picklist",
                  "label": "PAYMENT TERMS",
                  "type": "picklist",
                  "options": [
                    "Before Dispatch",
                    "Against LC Before Dispatch",
                    "Against VFS",
                    "Against PDC",
                    "Against Open Credit"
                  ],
                  "colSpan": 12
                },
                {
                  "apiName": "tc_lc_buyer_interest_days",
                  "label": "(I) USANCE INTEREST IN BUYER SCOPE(IN NUMBER OF DAYS)",
                  "type": "number",
                  "unit": "Days",
                  "colSpan": 12,
                  "controllingField": "tc_payment_terms_picklist",
                  "controllingValues": [
                    "Against LC Before Dispatch"
                  ]
                },
                {
                  "apiName": "tc_lc_seller_interest_days",
                  "label": "(II) USANCE INTEREST IN SELLER SCOPE(IN NUMBER OF DAYS)",
                  "type": "number",
                  "unit": "Days",
                  "colSpan": 12,
                  "controllingField": "tc_payment_terms_picklist",
                  "controllingValues": [
                    "Against LC Before Dispatch"
                  ]
                },

                {
                  "apiName": "tc_vfs_seller_interest",
                  "label": "INTEREST COMPONENT ON VFS FOR SELLER",
                  "type": "number",
                  "unit": "Days",
                  "colSpan": 12,
                  "controllingField": "tc_payment_terms_picklist",
                  "controllingValues": [
                    "Against VFS"
                  ]
                },
                {
                  "apiName": "tc_PDC_interest",
                  "label": "AGAINST PDC",
                  "type": "number",
                  "unit": "Days",
                  "colSpan": 12,
                  "controllingField": "tc_payment_terms_picklist",
                  "controllingValues": [
                    "Against PDC"
                  ]
                },
                {
                  "apiName": "tc_open_credit_days",
                  "label": "NO. OF OPEN CREDIT DAYS",
                  "type": "number",
                  "colSpan": 12,
                  "controllingField": "tc_payment_terms_picklist",
                  "controllingValues": [
                    "Against Open Credit"
                  ]
                }
              ]
            }
          ]
        }
      }
    }
  ]
}
